{
  "$schema": "https://claude.ai/schemas/plugin-marketplace/v1",
  "name": "claude-code-zero",
  "metadata": {
    "description": "personal collection of Claude Code plugins and tools"
  },
  "owner": {
    "name": "LeeJuOh",
    "email": "xop4p@naver.com"
  },
  "plugins": [
    {
      "name": "notebooklm-connector",
      "source": "./plugins/notebooklm-connector",
      "version": "1.2.0",
      "description": "A plugin to manage NotebookLM notebooks and query them using integrated features."
    },
    {
      "name": "toolbox",
      "source": "./plugins/toolbox",
      "version": "1.3.0",
      "description": "Personal utility commands and tools for Claude Code"
    },
    {
      "name": "plugin-bookmarks",
      "source": "./plugins/plugin-bookmarks",
      "version": "1.1.2",
      "description": "Bookmark third-party Claude Code plugins you want to remember"
    },
    {
      "name": "vision-powers",
      "source": "./plugins/vision-powers",
      "version": "2.6.0",
      "description": "Visual report generation suite: wiki analysis, diff review, plan review, project recap, fact-checking, and report management with interactive diagrams and curated design system"
    },
    {
      "name": "macos-notifier",
      "source": "./plugins/macos-notifier",
      "version": "1.0.0",
      "description": "Silent macOS desktop notifications when Claude Code needs attention"
    },
    {
      "name": "worktree-plus",
      "source": "./plugins/worktree-plus",
      "version": "2.4.2",
      "description": "Enhanced git worktree: custom branch prefix, remote branch tracking, selective copy/symlink for gitignored files, work state protection on cleanup"
    }
  ]
}
